import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

const workflow = readFileSync('.github/workflows/refresh-runner-report-lock.yml', 'utf8');
const publisher = readFileSync('.github/scripts/publish-runner-report-lock-pr.sh', 'utf8');
const stepNames = [...workflow.matchAll(/^      - name: (.+)$/gm)].map((match) => match[1]);
const step = (name) => {
  const body = workflow.split(`      - name: ${name}\n`)[1]?.split('      - name:')[0];
  assert.ok(body, `missing step ${name}`);
  return body;
};

test('report proof workflow is main-only and accepts no trust inputs', () => {
  assert.match(workflow, /^  workflow_dispatch:\r?\n  push:/m);
  assert.match(workflow, /branches: \[main\]/);
  assert.match(workflow, /if: github\.repository == 'groktopus\/proprio' && github\.ref == 'refs\/heads\/main'/);
  assert.match(workflow, /environment: lockfile-refresh/);
  assert.match(workflow, /DEFAULT_BRANCH: main/);
  assert.doesNotMatch(workflow, /\$\{\{\s*inputs\.|--trusted-lock-sha256\s+\$\{\{/);
  const validate = step('Validate default-branch and App identity configuration');
  assert.match(validate, /\[\[ -n "\$LOCKFILE_REFRESH_APP_CLIENT_ID" \]\]/);
  assert.match(validate, /\[\[ -n "\$APP_PRIVATE_KEY" \]\]/);
  assert.match(validate, /LOCKFILE_REFRESH_APP_LOGIN.*\[bot\]/);
});

test('proof creation requires recognized trusted main provenance before refresh or App token minting', () => {
  const trust = step('Verify trusted main lock provenance');
  const refresh = step('Validate resolution inputs and regenerate reporting proof');
  const token = step('Create repository-scoped refresh App token');
  assert.match(trust, /node \.github\/scripts\/lockfile-trust\.mjs merged/);
  assert.match(refresh, /TRUSTED_LOCK_SHA256: \$\{\{ steps\.trust\.outputs\.trusted_lock_sha256 \}\}/);
  assert.ok(stepNames.indexOf('Verify trusted main lock provenance') < stepNames.indexOf('Validate resolution inputs and regenerate reporting proof'));
  assert.ok(stepNames.indexOf('Validate resolution inputs and regenerate reporting proof') < stepNames.indexOf('Create repository-scoped refresh App token'));
  assert.match(refresh, /--refresh --trusted-lock-sha256 "\$TRUSTED_LOCK_SHA256"/);
  assert.match(refresh, /--trust-basis "\$TRUSTED_LOCK_BASIS"/);
  assert.match(trust, /lock_trust_basis/);
  assert.match(trust, /reviewed-main-bootstrap/);
  assert.equal(token.match(/secrets\.LOCKFILE_REFRESH_APP_PRIVATE_KEY/g)?.length, 1);
  assert.match(refresh, /refresh-runner-report-sdk-registry\.sh/);
  assert.ok(refresh.indexOf('prepare-report-lock.mjs --refresh') < refresh.indexOf('refresh-runner-report-sdk-registry.sh'));
});

test('App identity is matched to its token; PR writes use exact scopes and never merge', () => {
  const token = step('Create repository-scoped refresh App token');
  const identity = step('Verify configured identity matches the token App');
  const publish = step('Create or update the fixed proof PR');
  assert.match(token, /repositories: proprio/);
  assert.match(token, /permission-contents: write/);
  assert.match(token, /permission-pull-requests: write/);
  assert.match(identity, /\[\[ "\$\{APP_SLUG\}\[bot\]" == "\$EXPECTED_LOGIN" \]\]/);
  assert.match(publish, /bash \.github\/scripts\/publish-runner-report-lock-pr\.sh/);
  assert.match(publisher, /branch=chore\/refresh-lockfile/);
  assert.match(publisher, /head=groktopus%3Achore%2Frefresh-lockfile/);
  assert.match(publisher, /createCommitOnBranch/);
  assert.match(publisher, /branch:\{repositoryNameWithOwner:\$repository,branchName:\$branch\}/);
  assert.equal((publisher.match(/contents:\(\$(?:policy|patch|registry)\|@base64\)/g) ?? []).length, 3,
    'GraphQL FileAddition.contents must be Base64String for each exact file blob');
  assert.doesNotMatch(publisher, /contents:\$(?:policy|patch|registry)(?:[,}])/,
    'GraphQL FileAddition.contents must not send raw file strings');
  assert.match(publisher, /trusted main lock/);
  assert.match(publisher, /expectedHeadOid:\$base/);
  assert.match(publisher, /signature\.isValid/);
  assert.match(publisher, /signature\.wasSignedByGitHub/);
  assert.match(publisher, /\.author\.login/);
  assert.match(publisher, /\.commit\.verification\.verified/);
  assert.match(publisher, /\.parents\[0\]\.sha/);
  assert.match(publisher, /git fetch --no-tags origin "refs\/heads\/\$branch"/);
  assert.match(publisher, /Existing verified App branch has generated bytes that differ from this run/);
  assert.match(publisher, /tests\/runner-e2e\/source-sdk-public-inputs\.json/);
  assert.match(publisher, /gh pr create/);
  assert.doesNotMatch(publisher, /git push|--force|gh pr merge|--admin/);
  assert.doesNotMatch(workflow, /gh pr merge|--admin|GITHUB_TOKEN:.*write/);
});

test('only reporting proof and its generated SDK registry are staged for the fixed refresh PR', () => {
  const refresh = step('Validate resolution inputs and regenerate reporting proof');
  assert.match(refresh, /pnpm install --resolution-only --ignore-scripts --no-frozen-lockfile/);
  assert.match(refresh, /git add -- tests\/runner-e2e\/report-lock\.json tests\/runner-e2e\/report-lock\.patch tests\/runner-e2e\/source-sdk-public-inputs\.json/);
  assert.match(refresh, /pnpm-lock\.yaml\|tests\/runner-e2e\/report-lock\.json\|tests\/runner-e2e\/report-lock\.patch\|tests\/runner-e2e\/source-sdk-public-inputs\.json/);
  assert.match(refresh, /tests\/runner-e2e\/report-lock\.json\|tests\/runner-e2e\/report-lock\.patch\|tests\/runner-e2e\/source-sdk-public-inputs\.json/);
});
